                                    state: "ready" | "action_required" | "pending" | "paused" | "refused";
                                    reason?: {
                                        code: string;
                                        userMessage: string;
                                        details?: string;
                                    };
                                    /** @description The user's step: a `nextActions` key, `verify` (the identity check first) or `activate` (the provider's first use). */
